use vstd::prelude::*;
use vstd::seq::Seq;

verus! {
    fn copy(a: &Vec<u64>) -> (b: Vec<u64>)
        ensures
            b.len() == a.len(),
            b@ == a@,
    {
        // Pre‐allocate a new vector with the same capacity as `a`
        let mut b = Vec::with_capacity(a.len());
        
        // Push each element of `a` into `b`
        for &x in a.iter()
            invariant
                // b never grows beyond a
                b.len() <= a.len(),
                // at every point b exactly equals the prefix of a of length b.len()
                Seq::slice(a@, 0, b.len()) == b@,
            decreases
                // each iteration consumes one more element of a
                a.len() - b.len()
        {
            b.push(x);
        }
        
        b
    }
}

